set -eu
export PATH=/usr/sbin:/usr/bin:/sbin:/bin LC_ALL=C
fact() {
 key=$1; normalized=
 while :; do case "$key" in *-*) normalized="$normalized${key%%-*}_"; key="${key#*-}";; *) break;; esac; done
 printf 'FR_FACT %s=%s\n' "$normalized$key" "$2"; }
need() { for tool in "$@"; do if ! command -v "$tool" >/dev/null 2>&1; then printf 'FR_ERROR missing_tool=%s\n' "$tool" >&2; exit 127; fi; done; }
need sha256sum
hash_fact() {
 if test -f "$2" && test -r "$2"; then
  value=$(sha256sum "$2") || { printf 'FR_ERROR hash_failed=%s\n' "$2" >&2; exit 1; }
  set -- "$1" $value
  fact "$1" "$2"
 else fact "$1" missing; fi
}

